package vn.rtr.aeris.simhand01;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.system.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.*;import java.util.*;import java.util.concurrent.*;
/** Engineering USB-loopback shell; no flight command or authority persistence. */
public final class ShellActivity extends Activity{
 private static final String ORIGIN="http://127.0.0.1:8896";private static final int PACKAGE_MAX=32*1024*1024;private final String instance=UUID.randomUUID().toString();private volatile String session=UUID.randomUUID().toString();private volatile boolean foreground=false,destroyed=false;private boolean pickerOwned=false;private final OperationGate gate=new OperationGate();private long lastSequence=0;private WebView web;private WorkspaceStore store;private final ExecutorService io=Executors.newSingleThreadExecutor();private JSONObject pending;private byte[] exportBytes;private String exportSha;
 private JSONObject obj(Object...kv)throws Exception{JSONObject r=new JSONObject();for(int i=0;i<kv.length;i+=2)r.put((String)kv[i],kv[i+1]);return r;}
 private static boolean origin(String u){try{URI v=new URI(u);return"http".equals(v.getScheme())&&"127.0.0.1".equals(v.getHost())&&v.getPort()==8896&&v.getUserInfo()==null;}catch(Exception e){return false;}}
 private void directorySync(File dir)throws IOException{try{java.io.FileDescriptor fd=Os.open(dir.getPath(),OsConstants.O_RDONLY,0);try{Os.fsync(fd);}finally{Os.close(fd);}}catch(Exception e){throw new IOException("DIRECTORY_FSYNC",e);}}
 @Override public void onCreate(Bundle b){super.onCreate(b);try{store=new WorkspaceStore(new File(getFilesDir(),"workspace01"),this::directorySync,p->{});}catch(Exception e){fatal(e);return;}web=new WebView(this);web.setBackgroundColor(0xff101719);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setGeolocationEnabled(false);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setSupportMultipleWindows(false);s.setSaveFormData(false);web.addJavascriptInterface(new Broker(),"SimNative");
 web.setWebViewClient(new WebViewClient(){@Override public void onPageStarted(WebView w,String u,android.graphics.Bitmap icon){session=UUID.randomUUID().toString();lastSequence=0;}@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return!origin(r.getUrl().toString());}@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){if(origin(r.getUrl().toString()))return null;return new WebResourceResponse("text/plain","UTF-8",403,"Origin blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onConsoleMessage(ConsoleMessage m){android.util.Log.i("AERIS_SIMHAND01_JS",m.message()+" @"+m.sourceId()+":"+m.lineNumber());return true;}@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]>cb,FileChooserParams p){cb.onReceiveValue(null);return true;}});web.setDownloadListener((a,c,d,e,f)->Toast.makeText(this,"Dùng xuất SAF có kiểm SHA.",Toast.LENGTH_LONG).show());String path=getIntent().getStringExtra("initialPath");if(!Arrays.asList("/phone","/observer","/").contains(path))path="/phone";web.loadUrl(ORIGIN+path);}
 private void fatal(Exception e){TextView t=new TextView(this);t.setPadding(24,24,24,24);t.setText("AERIS SIM không mở dữ liệu: "+e.getMessage()+"\nKhông có quyền điều khiển được khôi phục.");setContentView(t);}
 public final class Broker{
 @JavascriptInterface public String environment(){try{return obj("format","aeris-simhand01-native","version",1,"platform","ANDROID","instance",instance,"session",session,"foreground",foreground,"package","vn.rtr.aeris.simhand01","authorityRestorable",false).toString();}catch(Exception e){return"{}";}}
 @JavascriptInterface public void request(String raw){if(raw==null||raw.length()>PACKAGE_MAX+8192||raw.getBytes(StandardCharsets.UTF_8).length>PACKAGE_MAX+8192)return;runOnUiThread(()->{JSONObject q=null;try{q=new JSONObject(raw);if(q.length()!=6||q.optDouble("version",0)!=1||!instance.equals(q.getString("instance"))||!session.equals(q.getString("session"))||!foreground||destroyed||!origin(web.getUrl()))throw new IOException("NATIVE_CONTEXT_REFUSED");String requestId=q.getString("id"),prefix=instance+":";if(!requestId.startsWith(prefix)||!requestId.substring(prefix.length()).matches("[1-9][0-9]{0,8}"))throw new IOException("NATIVE_REQUEST_ID");long seq=Long.parseLong(requestId.substring(prefix.length()));if(seq<=lastSequence)throw new IOException("NATIVE_REQUEST_REPLAY");if(gate.busy())throw new IOException("NATIVE_BUSY_NO_QUEUE");if(!Arrays.asList("load-workspace","save-workspace","export-session","import-session").contains(q.getString("action")))throw new IOException("NATIVE_ACTION_REFUSED");gate.begin(q.getString("session")+":"+requestId);lastSequence=seq;JSONObject request=q;io.execute(()->perform(request));}catch(Exception e){deliver(q,null,e,false);}});}}
 private void verifyContext(JSONObject q)throws Exception{if(!foreground||destroyed||!session.equals(q.getString("session")))throw new IOException("NATIVE_FOREGROUND_LOST");}
 private byte[] body(JSONObject args,int max)throws Exception{byte[]b=args.getString("body").getBytes(StandardCharsets.UTF_8);if(b.length>max||!WorkspaceStore.sha(b).equals(args.getString("bodySha256")))throw new IOException("BODY_SHA_OR_BOUND");JSONObject p=new JSONObject(new String(b,StandardCharsets.UTF_8));if(!p.optString("format").startsWith("aeris-simhand01")||p.optInt("version",0)!=1||p.optBoolean("authorityRestorable",true))throw new IOException("SIMULATION_PACKAGE_SCOPE");return b;}
 private JSONObject snapshot(WorkspaceStore.Snapshot s)throws Exception{return obj("status",s.status,"head",s.head,"body",s.body==null?JSONObject.NULL:s.body,"bodySha256",s.sha==null?JSONObject.NULL:s.sha,"platform","ANDROID","authorityRestored",false);}
 private void perform(JSONObject q){try{verifyContext(q);String action=q.getString("action");JSONObject a=q.getJSONObject("args");if(action.equals("load-workspace")){reply(q,snapshot(store.load()),null);return;}if(action.equals("save-workspace")){byte[]b=body(a,WorkspaceStore.MAX_BODY);verifyContext(q);reply(q,snapshot(store.save(a.getString("expectedHead"),new String(b,StandardCharsets.UTF_8))),null);return;}if(action.equals("export-session")){exportBytes=body(a,PACKAGE_MAX);exportSha=WorkspaceStore.sha(exportBytes);}pending=q;runOnUiThread(()->{try{verifyContext(q);pickerOwned=true;Intent intent=new Intent(action.equals("export-session")?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json");if(action.equals("export-session"))intent.putExtra(Intent.EXTRA_TITLE,"AERIS-SIM-session.json");startActivityForResult(intent,2203);}catch(Exception e){pickerOwned=false;pending=null;exportBytes=null;reply(q,null,e);}});}catch(Exception e){reply(q,null,e);}}
 private void reply(JSONObject q,JSONObject result,Exception error){deliver(q,result,error,true);}
 private void deliver(JSONObject q,JSONObject result,Exception error,boolean release){runOnUiThread(()->{if(release&&q!=null)gate.finish(q.optString("session")+":"+q.optString("id"));if(q==null||web==null||destroyed||!origin(web.getUrl()))return;try{JSONObject r=obj("version",1,"id",q.optString("id"),"instance",q.optString("instance"),"session",q.optString("session"),"action",q.optString("action"),"ok",error==null);if(error==null)r.put("result",result);else r.put("error",error.getMessage());web.evaluateJavascript("window.simNativeReply&&window.simNativeReply(JSON.parse("+JSONObject.quote(r.toString())+"))",null);}catch(Exception ignored){}});}
 @Override protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(req!=2203)return;JSONObject q=pending;pending=null;pickerOwned=false;if(q==null)return;if(code!=RESULT_OK||data==null||data.getData()==null){exportBytes=null;reply(q,null,new IOException("SAF_CANCELLED_NO_SUCCESS"));return;}Uri uri=data.getData();byte[]bytes=exportBytes;String expected=exportSha;exportBytes=null;io.execute(()->{try{if(!session.equals(q.getString("session"))||destroyed)throw new IOException("SAF_DOCUMENT_SESSION_CHANGED");JSONObject r;if(q.getString("action").equals("export-session")){if(bytes==null)throw new IOException("SAF_PENDING_BYTES_LOST");try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("SAF_OUTPUT_NULL");out.write(bytes);out.flush();}byte[]readback;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("SAF_READBACK_NULL");readback=WorkspaceStore.read(in,PACKAGE_MAX);}if(!WorkspaceStore.sha(readback).equals(expected)||readback.length!=bytes.length)throw new IOException("SAF_READBACK_MISMATCH_UNKNOWN_WRITE");r=obj("status","SAF_READBACK_VERIFIED","bodySha256",expected,"bytes",bytes.length);}else{byte[]b;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("SAF_INPUT_NULL");b=WorkspaceStore.read(in,PACKAGE_MAX);}String text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(b)).toString();new JSONObject(text);r=obj("status","PICK_READ_VERIFIED_UNTRUSTED_REQUIRES_HOST_VERIFY","body",text,"bodySha256",WorkspaceStore.sha(b));}r.put("platform","ANDROID");r.put("authorityRestored",false);reply(q,r,null);}catch(Exception e){reply(q,null,e);}});}
 @Override protected void onResume(){super.onResume();foreground=true;}
 @Override protected void onPause(){foreground=false;if(web!=null)web.evaluateJavascript("window.dispatchEvent(new CustomEvent('sim-native-background',{detail:{pickerOwned:"+pickerOwned+"}}));",null);super.onPause();}
 @Override protected void onDestroy(){destroyed=true;foreground=false;io.shutdown();if(web!=null){web.removeJavascriptInterface("SimNative");web.destroy();}super.onDestroy();}
}
